import React from "react";
import {
  AbsoluteFill,
  interpolate,
  useCurrentFrame,
  useVideoConfig,
  spring,
  Sequence,
} from "remotion";

// ============================================================
// STICKMAN FIGURE — SVG-based, animatable via props
// ============================================================
interface StickmanProps {
  x: number;
  y: number;
  armAngle: number; // degrees, 0 = arms down, -180 = arms overhead
  color?: string;
  scale?: number;
  opacity?: number;
}

const Stickman: React.FC<StickmanProps> = ({
  x,
  y,
  armAngle,
  color = "#e0e0e0",
  scale = 1,
  opacity = 1,
}) => {
  // Body measurements (relative to center-bottom)
  const headR = 18;
  const bodyLen = 70;
  const armLen = 50;
  const legLen = 55;
  const strokeW = 5;

  // Weapon: macuahuitl — paddle with obsidian teeth
  const weaponLength = 75;
  const paddleWidth = 14;
  const toothSize = 6;

  return (
    <g
      transform={`translate(${x}, ${y}) scale(${scale})`}
      opacity={opacity}
    >
      {/* Legs — standing pose, slight spread */}
      <line
        x1={0} y1={0}
        x2={-18} y2={legLen}
        stroke={color} strokeWidth={strokeW} strokeLinecap="round"
      />
      <line
        x1={0} y1={0}
        x2={18} y2={legLen}
        stroke={color} strokeWidth={strokeW} strokeLinecap="round"
      />

      {/* Body */}
      <line
        x1={0} y1={0}
        x2={0} y2={-bodyLen}
        stroke={color} strokeWidth={strokeW} strokeLinecap="round"
      />

      {/* Head */}
      <circle
        cx={0} cy={-bodyLen - headR}
        r={headR}
        fill="none" stroke={color} strokeWidth={strokeW}
      />

      {/* Arms — both holding the weapon, rotate together */}
      <g transform={`rotate(${armAngle}, 0, ${-bodyLen + 15})`}>
        {/* Left arm */}
        <line
          x1={0} y1={-bodyLen + 15}
          x2={-12} y2={-bodyLen + 15 - armLen}
          stroke={color} strokeWidth={strokeW} strokeLinecap="round"
        />
        {/* Right arm */}
        <line
          x1={0} y1={-bodyLen + 15}
          x2={12} y2={-bodyLen + 15 - armLen}
          stroke={color} strokeWidth={strokeW} strokeLinecap="round"
        />

        {/* MACUAHUITL — the obsidian club */}
        <g transform={`translate(0, ${-bodyLen + 15 - armLen})`}>
          {/* Main paddle shaft */}
          <rect
            x={-paddleWidth / 2}
            y={-weaponLength}
            width={paddleWidth}
            height={weaponLength}
            rx={3}
            fill="#5c3a1e"
            stroke="#3d2510"
            strokeWidth={1.5}
          />

          {/* Obsidian teeth — left side */}
          {[0, 1, 2, 3, 4, 5].map((i) => (
            <polygon
              key={`left-${i}`}
              points={`${-paddleWidth / 2 - toothSize},${-10 - i * 11} ${-paddleWidth / 2},${-7 - i * 11} ${-paddleWidth / 2},${-13 - i * 11}`}
              fill="#1a1a2e"
              stroke="#0d0d1a"
              strokeWidth={0.5}
            />
          ))}

          {/* Obsidian teeth — right side */}
          {[0, 1, 2, 3, 4, 5].map((i) => (
            <polygon
              key={`right-${i}`}
              points={`${paddleWidth / 2 + toothSize},${-10 - i * 11} ${paddleWidth / 2},${-7 - i * 11} ${paddleWidth / 2},${-13 - i * 11}`}
              fill="#1a1a2e"
              stroke="#0d0d1a"
              strokeWidth={0.5}
            />
          ))}
        </g>
      </g>
    </g>
  );
};

// ============================================================
// MAIN SCENE — Cold Open (10 seconds)
// ============================================================
export const ColdOpen: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // --- TIMING (in frames at 30fps) ---
  // 0-60:   Fade in stickman (2 sec)
  // 60-150: Raise weapon overhead (3 sec)
  // 150-210: Swing down (2 sec)
  // 210-240: Red flash on impact (1 sec)
  // 240-300: Black screen + title fade (2 sec)

  // Stickman fade in
  const stickmanOpacity = interpolate(frame, [0, 45], [0, 1], {
    extrapolateRight: "clamp",
  });

  // Arm angle: 0 = arms at sides, -180 = arms straight up
  const armRaise = interpolate(frame, [60, 150], [20, -170], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Swing down: -170 up → 70 down (past horizontal) with easing
  const swingDown = interpolate(frame, [150, 195], [-170, 80], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Use raise during raise phase, swing during swing phase
  const armAngle = frame < 150 ? armRaise : swingDown;

  // Red flash
  const flashOpacity = interpolate(frame, [195, 205, 215, 225], [0, 0.7, 0.7, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Black fade after impact
  const blackFade = interpolate(frame, [220, 240], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Title text fade in
  const titleOpacity = interpolate(frame, [250, 275], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Subtle camera zoom during raise
  const cameraScale = interpolate(frame, [60, 195], [1, 1.15], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Ground line position
  const groundY = height * 0.78;

  return (
    <AbsoluteFill
      style={{
        backgroundColor: "#0a0a0f",
        overflow: "hidden",
      }}
    >
      {/* Subtle dark gradient background */}
      <div
        style={{
          position: "absolute",
          width: "100%",
          height: "100%",
          background:
            "radial-gradient(ellipse at 50% 70%, #1a1520 0%, #0a0a0f 70%)",
        }}
      />

      {/* Red rim light glow (left side) */}
      <div
        style={{
          position: "absolute",
          left: -100,
          top: "30%",
          width: 300,
          height: 400,
          background: "radial-gradient(circle, rgba(180,30,30,0.15) 0%, transparent 70%)",
          filter: "blur(40px)",
        }}
      />

      {/* SVG Scene */}
      <svg
        width={width}
        height={height}
        viewBox={`0 0 ${width} ${height}`}
        style={{
          position: "absolute",
          transform: `scale(${cameraScale})`,
          transformOrigin: `${width / 2}px ${groundY - 60}px`,
        }}
      >
        {/* Ground line */}
        <line
          x1={0}
          y1={groundY}
          x2={width}
          y2={groundY}
          stroke="#2a2a35"
          strokeWidth={2}
          opacity={0.5}
        />

        {/* THE STICKMAN */}
        <Stickman
          x={width / 2}
          y={groundY}
          armAngle={armAngle}
          opacity={stickmanOpacity}
          scale={1.3}
        />
      </svg>

      {/* RED FLASH on impact */}
      <div
        style={{
          position: "absolute",
          width: "100%",
          height: "100%",
          backgroundColor: "#8b0000",
          opacity: flashOpacity,
        }}
      />

      {/* BLACK FADE after impact */}
      <div
        style={{
          position: "absolute",
          width: "100%",
          height: "100%",
          backgroundColor: "#000000",
          opacity: blackFade,
        }}
      />

      {/* TITLE CARD */}
      {frame >= 240 && (
        <div
          style={{
            position: "absolute",
            width: "100%",
            height: "100%",
            display: "flex",
            flexDirection: "column",
            alignItems: "center",
            justifyContent: "center",
            opacity: titleOpacity,
          }}
        >
          <h1
            style={{
              fontFamily: "Arial Black, Impact, sans-serif",
              fontSize: 62,
              fontWeight: 900,
              color: "#ffffff",
              textTransform: "uppercase",
              letterSpacing: 6,
              textAlign: "center",
              lineHeight: 1.2,
              textShadow: "0 0 40px rgba(139,0,0,0.6), 0 0 80px rgba(139,0,0,0.3)",
              margin: 0,
              padding: "0 80px",
            }}
          >
            The Most Terrifying
            <br />
            Weapons Ever Banned
          </h1>
        </div>
      )}
    </AbsoluteFill>
  );
};

import { Composition } from "remotion";
import { ColdOpen } from "./ColdOpen";

export const RemotionRoot: React.FC = () => {
  return (
    <>
      <Composition
        id="ColdOpen"
        component={ColdOpen}
        durationInFrames={300}
        fps={30}
        width={1920}
        height={1080}
      />
    </>
  );
};
